    {status==='complete'&&<div className="mining-result"><div className="mining-result__head"><span className="completion-card__icon"><Check size={20}/></span><div><small>mine_20261007_0118_f6c2 · Complete</small><h3>{count(budget)} / {count(budget)} selected</h3><p>{strategy} · {executor} · 47m 12s</p></div><Badge>EXACT-N</Badge></div><div className="result-pipeline">{['Prepare data','Inference','Embedding','Scoring','Selection','Publish'].map(s=><span key={s}><Check size={12}/>{s}</span>)}</div><div className="result-output"><div><small>Created selection batch</small><strong>{batchName}</strong><span>{count(budget)} selected · awaiting review</span></div><div><small>Artifacts</small><strong>scores.parquet · selected.json</strong><span>statistics.json · run_result.json</span></div><Button variant="primary" icon={ArrowRight} onClick={()=>navigate('data-explorer')}>Review selected batch</Button></div></div>}
