export function Labeling({ notify }) {
  const [index, setIndex] = useState(0); const [category, setCategory] = useState('Car'); const [tool, setTool] = useState('box'); const [boxes, setBoxes] = useState({}); const [draft, setDraft] = useState(null); const [active, setActive] = useState(null); const canvas = useRef(null); const start = useRef(null);
  const current = boxes[index] || [{ id: 'default-car', x: 43, y: 54, w: 19, h: 20, label: 'Car' }];
  const point = e => { const bounds = canvas.current.getBoundingClientRect(); return { x: Math.max(0, Math.min(100, (e.clientX - bounds.left) / bounds.width * 100)), y: Math.max(0, Math.min(100, (e.clientY - bounds.top) / bounds.height * 100)) }; };
  const begin = e => { if (tool !== 'box' || e.button !== 0 || e.target.closest('.annotation-box')) return; start.current = point(e); canvas.current.setPointerCapture(e.pointerId); setDraft({ ...start.current, w: 0, h: 0 }); };
  const move = e => { if (!start.current) return; const p = point(e), s = start.current; setDraft({ x: Math.min(s.x, p.x), y: Math.min(s.y, p.y), w: Math.abs(s.x - p.x), h: Math.abs(s.y - p.y) }); };
  const end = e => { if (!start.current) return; if (draft && draft.w > 2 && draft.h > 2) { const box = { ...draft, id: `box-${Date.now()}`, label: category }; setBoxes(value => ({ ...value, [index]: [...current, box] })); setActive(box.id); } start.current = null; setDraft(null); canvas.current.releasePointerCapture?.(e.pointerId); };
  const save = () => { try { localStorage.setItem('roadsift-mock-annotations', JSON.stringify(boxes)); notify('Demo labels saved in this browser'); } catch { notify('Browser storage unavailable; labels remain in this session'); } };
  useEffect(() => { try { const saved = JSON.parse(localStorage.getItem('roadsift-mock-annotations')); if (saved) setBoxes(saved); } catch {} }, []);
  return <div className="page"><PageHeader eyebrow="Human in the loop" title="Label editor" description="Bring your judgment to every frame." actions={<Button variant="primary" icon={Save} onClick={save}>Save demo labels</Button>} /><div className="annotation-toolbar"><Segmented label="Annotation tool" value={tool} onChange={setTool} options={[{ value: 'select', label: 'Select', icon: MousePointer2 }, { value: 'box', label: 'Draw box', icon: BoxSelect }]} /><span>Frame {index + 1} of {frames.length}</span><div><Button aria-label="Previous frame" icon={ArrowLeft} disabled={index === 0} onClick={() => { setIndex(v => v - 1); setActive(null); }} /><Button aria-label="Next frame" icon={ArrowRight} disabled={index === frames.length - 1} onClick={() => { setIndex(v => v + 1); setActive(null); }} /></div></div><div className="annotation-layout"><div><div className={`annotation-canvas annotation-canvas--${tool}`} ref={canvas} onPointerDown={begin} onPointerMove={move} onPointerUp={end} onPointerCancel={() => { start.current = null; setDraft(null); }}><Scene scene={frames[index].scene} />{current.map(b => <button key={b.id} aria-label={`${b.label} annotation`} className={`annotation-box ${active === b.id ? 'annotation-box--active' : ''}`} style={{ left: `${b.x}%`, top: `${b.y}%`, width: `${b.w}%`, height: `${b.h}%` }} onPointerDown={e => e.stopPropagation()} onClick={() => setActive(b.id)}><span>{b.label}</span></button>)}{draft && <div className="annotation-box annotation-box--draft" style={{ left: `${draft.x}%`, top: `${draft.y}%`, width: `${draft.w}%`, height: `${draft.h}%` }} />}</div><div className="canvas-caption"><Crosshair size={14} /><span>{tool === 'box' ? 'Click and drag to draw a bounding box' : 'Click an annotation to select it'}</span><span>Illustrated demo frame</span></div><div className="filmstrip">{frames.slice(0, 12).map((f, i) => <button key={f.id} className={index === i ? 'filmstrip__frame filmstrip__frame--active' : 'filmstrip__frame'} aria-label={`Open frame ${i + 1}`} onClick={() => { setIndex(i); setActive(null); }}><Scene scene={f.scene} /><span>{i + 1}</span></button>)}</div></div><Panel title="Annotations" description={`${current.length} objects in this frame`}><Field label="New object class"><select value={category} onChange={e => setCategory(e.target.value)}>{['Car', 'Pedestrian', 'Cyclist', 'Truck', 'Bus'].map(c => <option key={c}>{c}</option>)}</select></Field><div className="annotation-list">{current.map((b, i) => <div className={active === b.id ? 'annotation-item annotation-item--active' : 'annotation-item'} key={b.id}><button onClick={() => setActive(b.id)}><span>{i + 1}</span>{b.label}</button><button aria-label={`Delete ${b.label} annotation ${i + 1}`} onClick={() => { setBoxes(value => ({ ...value, [index]: current.filter(box => box.id !== b.id) })); setActive(null); }}><Trash2 size={14} /></button></div>)}</div><DemoNote>Labels are stored locally, never uploaded.</DemoNote></Panel></div></div>;
}

export function Training({ datasets, notify, navigate }) {
  const [dataset, setDataset] = useState(datasets.find(d => d.stage === 'Labeled')?.id || datasets[0]?.id); const [epochs, setEpochs] = useState('20'); const [runner, setRunner] = useState('local');
  const sim = useSimulation(() => notify('Training simulation complete — demo metrics are ready'));
  const active = ['running', 'paused'].includes(sim.status);
  return <div className="page"><PageHeader eyebrow="The next iteration" title="Training" description="Good data makes better models. Preview the next step." actions={<Button icon={ChartNoAxesCombined} onClick={() => navigate('metrics')}>Model metrics</Button>} /><div className="metrics-grid metrics-grid--three"><Metric label="Base model" value="YOLO11n" detail="Demo model configuration" icon={Cpu} /><Metric label="Training samples" value={count(datasets.find(d => d.id === dataset)?.count || 0)} detail="Selected collection" icon={Database} tone="purple" /><Metric label="Demo runner" value={runner === 'local' ? 'Local' : 'Cloud'} detail="Interface simulation only" icon={Monitor} tone="green" /></div><div className="two-column two-column--config"><Panel title="Training setup" description="Configure your next experiment."><Field label="Dataset"><select value={dataset} disabled={active} onChange={e => setDataset(e.target.value)}>{datasets.map(d => <option key={d.id} value={d.id}>{d.name} · {d.stage}</option>)}</select></Field><Field label="Base checkpoint"><select disabled={active}><option>YOLO11n · champion_v1</option><option>YOLO11s · baseline</option></select></Field><div className="config-fields"><Field label="Epochs"><select disabled={active} value={epochs} onChange={e => setEpochs(e.target.value)}>{['10', '20', '50', '100'].map(v => <option key={v}>{v}</option>)}</select></Field><Field label="Batch size"><select disabled={active}><option>16</option><option>32</option><option>64</option></select></Field></div><Field label="Runner"><Segmented value={runner} onChange={value => { if (!active) setRunner(value); }} label="Training runner" options={[{ value: 'local', label: 'Local', icon: Cpu }, { value: 'cloud', label: 'Cloud', icon: Cloud }]} /></Field><Button variant="primary" className="wide" icon={Play} disabled={active} onClick={sim.start}>Start training simulation</Button><DemoNote>No model is trained. No GPU or cloud job is launched.</DemoNote></Panel><Panel title="Experiment progress" description="A preview of the training experience."><div className="job-status"><span className={`job-icon ${sim.status === 'running' ? 'job-icon--running' : ''}`}><ChartNoAxesCombined size={25} /></span><h3>{sim.status === 'idle' ? 'Your next model starts here' : sim.status === 'complete' ? 'Experiment preview complete' : sim.status === 'paused' ? 'Simulation paused' : 'Training simulation in progress'}</h3><p>{sim.status === 'idle' ? 'Start the simulation to see progress and example learning curves.' : 'All values below are illustrative demo metrics.'}</p></div><Progress value={sim.progress} label={`Demo epoch ${Math.floor(sim.progress / 100 * Number(epochs))} / ${epochs}`} /><LearningChart progress={sim.progress} /><div className="chart-legend"><span><i className="legend-blue" />Training loss</span><span><i className="legend-purple" />Validation loss</span><Badge>Simulated</Badge></div><div className="job-actions">{sim.status === 'running' && <Button icon={Pause} onClick={sim.pause}>Pause</Button>}{sim.status === 'paused' && <Button icon={Play} onClick={sim.resume}>Resume</Button>}{sim.status === 'complete' && <Button variant="primary" icon={ArrowRight} onClick={() => navigate('metrics')}>Explore demo metrics</Button>}</div></Panel></div></div>;
}
function LearningChart({ progress = 100 }) { const width = Math.max(1, progress / 100 * 500); return <div className="learning-chart"><svg viewBox="0 0 560 180" role="img" aria-label="Illustrative training and validation loss curves"><defs><clipPath id="loss-reveal"><rect x="35" y="0" width={width} height="180" /></clipPath></defs>{[30, 70, 110, 150].map((y, i) => <g key={y}><line x1="35" x2="535" y1={y} y2={y} className="chart-grid" /><text x="5" y={y + 4}>{(1.6 - i * .4).toFixed(1)}</text></g>)}<g clipPath="url(#loss-reveal)"><path d="M35 30 C65 70 75 85 100 88 S150 115 185 123 S260 140 300 145 S430 158 535 160" className="chart-line chart-line--blue" /><path d="M35 45 C70 58 80 92 100 90 S150 103 185 112 S250 128 300 132 S410 135 450 140 S500 140 535 143" className="chart-line chart-line--purple" /></g><text x="35" y="178">0</text><text x="260" y="178">Epochs</text><text x="515" y="178">20</text></svg></div>; }

export function Metrics({ notify }) {
  const [compare, setCompare] = useState(false);
  return <div className="page"><PageHeader eyebrow="Measure what matters" title="Model metrics" description="A clearer picture of how your model sees the world." actions={<><Button icon={Layers} onClick={() => setCompare(v => !v)}>{compare ? 'Hide baseline' : 'Compare baseline'}</Button><Button icon={Download} onClick={() => { downloadJSON('demo-model-metrics.json', { demo: true, metrics }); notify('Demo metrics exported'); }}>Export demo report</Button></>} /><div className="metrics-grid"><Metric label="mAP @ 50" value="85.6%" detail={compare ? '+3.2 pts vs demo baseline' : 'Across five demo classes'} icon={Target} /><Metric label="Precision" value="87.2%" detail={compare ? '+1.8 pts vs demo baseline' : 'Illustrative evaluation value'} icon={Crosshair} tone="purple" /><Metric label="Recall" value="83.4%" detail={compare ? '+2.4 pts vs demo baseline' : 'Illustrative evaluation value'} icon={ScanLine} tone="green" /><Metric label="Inference latency" value="12.8 ms" detail="Demo value · not a benchmark" icon={Cpu} tone="orange" /></div><div className="two-column two-column--metrics"><Panel title="Performance by class" description="Demo checkpoint · challenger_v2" actions={<Badge>Sample results</Badge>}><div className="class-bars">{metrics.map(m => <div key={m.label}><div><strong>{m.label}</strong><span>{(m.ap * 100).toFixed(1)}%</span></div><div className="class-bar"><i style={{ width: `${m.ap * 100}%` }} />{compare && <b style={{ left: `${(m.ap - .032) * 100}%` }} title="Demo baseline" />}</div></div>)}</div><div className="table-scroll"><table><thead><tr><th>Class</th><th>Precision</th><th>Recall</th><th>Instances</th></tr></thead><tbody>{metrics.map(m => <tr key={m.label}><td>{m.label}</td><td>{(m.precision * 100).toFixed(1)}%</td><td>{(m.recall * 100).toFixed(1)}%</td><td>{count(m.count)}</td></tr>)}</tbody></table></div></Panel><Panel title="Evaluation context" description="Know what sits behind the numbers."><StatRow label="Checkpoint" value="challenger_v2" /><StatRow label="Dataset" value="Validation holdout" /><StatRow label="Evaluation frames" value="300" /><StatRow label="Classes" value="5" /><StatRow label="Evidence" value="Demo fixture" /><div className="insight"><span><Sparkles size={18} /></span><h3>A useful comparison</h3><p>Explore per-class results alongside overall scores. In a real run, model selection should happen on validation before a final held-out test.</p></div><DemoNote>No real training or evaluation results are represented.</DemoNote></Panel></div></div>;
}

export function PAL({ notify, navigate }) {
  const [strategy, setStrategy] = useState('PAL'); const [budget, setBudget] = useState('32'); const sim = useSimulation(() => notify('Acquisition simulation complete'));
  return <div className="page"><PageHeader eyebrow="Learn with intention" title="PAL Workbench" description="Explore how acquisition strategies choose the next best frames." actions={<Button icon={ArrowRight} onClick={() => navigate('data-explorer')}>Open explorer</Button>} /><div className="metrics-grid metrics-grid--three"><Metric label="Demo pool" value="2,400" detail="Sample unlabeled frames" icon={Database} /><Metric label="Annotation budget" value={budget} detail="Frames per acquisition round" icon={ScanLine} tone="purple" /><Metric label="Acquisition strategy" value={strategy} detail="Simulated selection" icon={Sparkles} tone="green" /></div><div className="two-column two-column--config"><Panel title="Acquisition setup" description="Choose how to spend your labeling budget."><Field label="Strategy"><select value={strategy} onChange={e => setStrategy(e.target.value)} disabled={sim.status === 'running'}>{['PAL', 'Uncertainty', 'Random', 'RAV-05'].map(v => <option key={v}>{v}</option>)}</select></Field><Field label="Acquisition budget"><select value={budget} onChange={e => setBudget(e.target.value)} disabled={sim.status === 'running'}>{['16', '32', '64', '128'].map(v => <option key={v}>{v}</option>)}</select></Field><div className="insight insight--plain"><Crosshair size={22} /><h3>Coverage meets uncertainty</h3><p>PAL combines learning signals with class coverage. This prototype lets you explore the interaction without running an acquisition model.</p></div><Button variant="primary" className="wide" icon={Sparkles} onClick={sim.start} disabled={sim.status === 'running'}>Run demo acquisition</Button><DemoNote>UI simulation · no model inference</DemoNote></Panel><Panel title="Selection preview" description="A glimpse of the next learning round.">{sim.status === 'idle' ? <Empty title="Make room for the next insight" detail="Run the demo to preview a selection of illustrated frames." /> : <><Progress value={sim.progress} label="Demo acquisition" /><div className="acquisition-preview">{frames.slice(0, sim.status === 'complete' ? 6 : Math.floor(sim.progress / 17)).map(f => <div key={f.id}><Scene scene={f.scene} /><span>{f.id}</span></div>)}</div>{sim.status === 'complete' && <div className="acquisition-result"><CheckCircle2 size={20} /><div><strong>Demo selection ready</strong><p>Six illustrated previews represent your {budget}-frame budget.</p></div><Button onClick={() => navigate('labeling')}>Review labels</Button></div>}</>}</Panel></div></div>;
}

export function SettingsPage({ theme, setTheme, preferences, setPreferences, setDatasets, setRuns, notify, language='en', setLanguage }) {
  const [resetOpen, setResetOpen] = useState(false);
  const vi=language==='vi';
  return <div className="page settings-page"><PageHeader eyebrow={vi?'Tùy chỉnh':'Make it yours'} title={vi?'Cài đặt':'Settings'} description={vi?'Thiết lập giao diện và tùy chọn workspace.':'A workspace that feels right, down to the details.'} /><Panel title={vi?'Ngôn ngữ':'Language'} description={vi?'Chọn ngôn ngữ giao diện. Thuật ngữ kỹ thuật vẫn giữ English.':'Choose the interface language. Technical terms remain in English.'}><div className="language-options"><button className={language==='en'?'language-card language-card--active':'language-card'} onClick={()=>setLanguage?.('en')}><strong>English</strong><span>EN</span></button><button className={language==='vi'?'language-card language-card--active':'language-card'} onClick={()=>setLanguage?.('vi')}><strong>Tiếng Việt</strong><span>VI</span></button></div></Panel><Panel title={vi?'Giao diện':'Appearance'} description={vi?'Chọn cách RoadSift hiển thị trên màn hình.':'Choose how RoadSift looks on your screen.'}><div className="appearance-options">{[['light', 'Light', Sun], ['dark', 'Dark', Moon]].map(([value, title, Icon]) => <button key={value} className={`appearance-card appearance-card--${value} ${theme === value ? 'appearance-card--active' : ''}`} aria-pressed={theme === value} onClick={() => setTheme(value)}><div className="appearance-preview"><aside /><section><i /><b /><b /><b /></section></div><span><Icon size={16} />{title}{theme === value && <CheckCircle2 size={16} />}</span></button>)}</div><div className="settings-row"><div><strong>{vi?'Danh sách gọn':'Compact lists'}</strong><p>{vi?'Hiển thị nhiều dòng dữ liệu hơn trong workspace.':'Fit more dataset rows into your workspace.'}</p></div><Toggle label="Compact lists" checked={preferences.compact} onChange={value => setPreferences(p => ({ ...p, compact: value }))} /></div><div className="settings-row"><div><strong>{vi?'Hiệu ứng giao diện':'Interface animations'}</strong><p>{vi?'Hiệu ứng chuyển động nhẹ cho panel và điều hướng.':'Subtle transitions for panels and navigation.'}</p></div><Toggle label="Interface animations" checked={preferences.animations} onChange={value => setPreferences(p => ({ ...p, animations: value }))} /></div></Panel><Panel title={vi?'Dữ liệu cục bộ':'Local workspace'} description={vi?'Các tùy chọn được lưu trong trình duyệt này.':'Your preferences are stored in this browser.'}><StatRow label="Data source" value="Bundled demo fixtures" /><StatRow label="Backend connection" value="Not required" /><StatRow label="Persistence" value="Browser localStorage" /><div className="settings-row"><div><strong>Reset demo data</strong><p>Restore the sample catalog, history, and saved labels.</p></div><Button icon={RotateCcw} onClick={() => setResetOpen(true)}>Reset</Button></div></Panel>{resetOpen && <Modal title="Reset demo data?" onClose={() => setResetOpen(false)} footer={<><Button onClick={() => setResetOpen(false)}>Cancel</Button><Button variant="primary" onClick={() => { setDatasets(initialDatasets); setRuns(initialRuns); try { localStorage.removeItem('roadsift-mock-annotations'); } catch {} setResetOpen(false); notify('Sample catalog, history, and labels reset'); }}>Reset demo data</Button></>}><p>Your locally added demo dataset records, simulated mining history, and saved demo labels will be replaced with the original fixtures. Theme and appearance preferences are preserved.</p></Modal>}</div>;
}

export function SystemPage({ notify }) {
  const [runnerOpen,setRunnerOpen]=useState(false);
  const [runnerName,setRunnerName]=useState('Kaggle T4 Runner');
  const [runnerType,setRunnerType]=useState('Kaggle');
  const [endpoint,setEndpoint]=useState('kaggle://roadsift/mining-t4');
  const registerRunner=()=>{ setRunnerOpen(false); notify?.(`${runnerName} registered for Mining`); };
  return <div className="page settings-page"><PageHeader eyebrow="Infrastructure" title="System" description="Register the execution and storage services RoadSift uses for mining and handoff." actions={<Button variant="primary" icon={Plus} onClick={()=>setRunnerOpen(true)}>Register runner</Button>} />
    <div className="two-column">
      <Panel title="Mining runners" description="Execution backends available to Mining."><div className="system-resource"><div><strong>Kaggle GPU · T4</strong><p>Kaggle executor · active</p></div><Badge tone="complete">Ready</Badge></div><div className="system-resource"><div><strong>RoadSift Worker</strong><p>Production worker · not registered</p></div><Badge>Offline</Badge></div></Panel>
      <Panel title="Connected services" description="External systems referenced by RoadSift workflows."><StatRow label="Artifact storage" value="Cloudflare R2 · connected"/><StatRow label="Annotation handoff" value="CVAT / Label Studio · external"/><StatRow label="Model registry" value="External artifacts · reference only"/><StatRow label="Evaluation" value="Fixed holdout results · registered"/></Panel>
    </div>
    <Panel title="Mining execution contract" description="A runner receives an immutable job spec and writes artifacts back to object storage."><div className="provenance-grid"><StatRow label="Input" value="Pool snapshot + Dataset version"/><StatRow label="Acquisition model" value="Registered model artifact"/><StatRow label="Job spec" value="strategy + budget + weights"/><StatRow label="Output" value="Selection Batch + run artifacts"/></div></Panel>
    {runnerOpen&&<Modal title="Register mining runner" onClose={()=>setRunnerOpen(false)} footer={<><Button onClick={()=>setRunnerOpen(false)}>Cancel</Button><Button variant="primary" onClick={registerRunner}>Register runner</Button></>}><Field label="Runner name"><input value={runnerName} onChange={e=>setRunnerName(e.target.value)}/></Field><Field label="Runner type"><select value={runnerType} onChange={e=>setRunnerType(e.target.value)}><option>Kaggle</option><option>RoadSift Worker</option><option>Custom</option></select></Field><Field label="Endpoint / runner URI"><input value={endpoint} onChange={e=>setEndpoint(e.target.value)} /></Field></Modal>}
  </div>;
}

export function Onboarding({ navigate }) {
  return <div className="page documentation-page"><PageHeader eyebrow="Start here" title="Onboarding" description="RoadSift helps perception teams spend labeling budget on the frames that matter most." />
    <div className="onboarding-hero"><div><h2>Two expensive problems.<br/>One data-selection workflow.</h2><p>Fleet data grows much faster than teams can inspect or label it. RoadSift turns that raw pool into smaller, traceable batches for annotation and model improvement.</p><Button variant="primary" icon={ArrowRight} onClick={()=>navigate('pools')}>Open Pools</Button></div></div>
    <div className="onboarding-problems">
      <Panel title="Problem 1 · Too much unlabeled fleet data" description="Millions of near-duplicate or low-value frames make manual sampling expensive."><p>RoadSift registers immutable Pool snapshots, filters eligibility, scores candidates and selects an exact annotation budget.</p></Panel>
      <Panel title="Problem 2 · Hard to prove which data is worth labeling" description="A larger dataset is not automatically a better dataset."><p>RoadSift preserves lineage across Dataset versions and compares acquisition strategies using the same training recipe and fixed holdout.</p></Panel>
    </div>
    <Panel title="Workflow" description="The product boundary in one line."><div className="onboarding-flow"><span>Import</span><ArrowRight size={14}/><span>Pool</span><ArrowRight size={14}/><span>Mining</span><ArrowRight size={14}/><span>Selection Batch</span><ArrowRight size={14}/><span>External Annotation</span><ArrowRight size={14}/><span>Dataset Version</span></div></Panel>
    <div className="onboarding-summary"><div><small>Market</small><strong>Perception teams already pay heavily for storage, annotation and retraining; RoadSift targets the data-selection layer between fleet collection and labeling.</strong></div><div><small>ROI</small><strong>ROI = avoided annotation cost + faster model gain − mining / compute cost.</strong><p>Measure it as model improvement per 1,000 labeled frames, per annotation hour, and per dollar.</p></div></div>
  </div>;
}

export function StrategyComparison({ datasets, navigate }) {
  const entropy=datasets.filter(d=>d.strategy==='Entropy Sampling').sort((a,b)=>a.version-b.version);
  const hybrid=datasets.filter(d=>d.strategy==='Hybrid Sampling').sort((a,b)=>a.version-b.version);
  const points=[
    {label:'Seed',samples:8000,entropy:.381,hybrid:.381},
    {label:'Round 1',samples:12000,entropy:entropy[0]?.evaluation?.map??.409,hybrid:hybrid[0]?.evaluation?.map??.417},
    {label:'Round 2',samples:16000,entropy:entropy[1]?.evaluation?.map??.425,hybrid:hybrid[1]?.evaluation?.map??.441},
  ];
  const max=.46,min=.36,xy=(p,i,key)=>({x:8+i*42,y:88-((p[key]-min)/(max-min))*70});
  const path=key=>points.map((p,i)=>{const q=xy(p,i,key);return `${i?'L':'M'} ${q.x} ${q.y}`}).join(' ');
  return <div className="page comparison-page"><PageHeader eyebrow="Active learning evaluation" title="Strategy Comparison" description="Compare acquisition strategies at the same labeled budget on the same fixed holdout." actions={<Button icon={Pickaxe} onClick={()=>navigate('mining')}>New mining run</Button>}/>
    <div className="comparison-contract"><span><small>Initial labeled set</small><strong>8,000 frames</strong></span><span><small>Budget / round</small><strong>4,000 frames</strong></span><span><small>Training recipe</small><strong>YOLO11m · controlled</strong></span><span><small>Evaluation</small><strong>Fixed Holdout v1 · 12,000</strong></span></div>
    <div className="comparison-grid"><Panel title="Learning curve" description="Higher mAP50–95 at the same cumulative annotation budget means greater data-selection efficiency."><div className="learning-chart"><div className="learning-chart__legend"><span><i/>Entropy Sampling</span><span><i/>Hybrid Sampling</span></div><svg viewBox="0 0 100 100" role="img" aria-label="Learning curve comparing Entropy and Hybrid Sampling"><line x1="8" y1="88" x2="92" y2="88"/><line x1="8" y1="18" x2="8" y2="88"/><path className="curve curve--entropy" d={path('entropy')}/><path className="curve curve--hybrid" d={path('hybrid')}/>{points.map((p,i)=>{const e=xy(p,i,'entropy'),h=xy(p,i,'hybrid');return <g key={p.label}><circle className="dot dot--entropy" cx={e.x} cy={e.y} r="2"/><circle className="dot dot--hybrid" cx={h.x} cy={h.y} r="2"/><text x={e.x} y="97" textAnchor="middle">{p.samples/1000}k</text></g>})}</svg><div className="learning-chart__axis">Cumulative labeled frames</div></div></Panel>
      <Panel title="Round 2 result" description="Same 16,000 labeled-frame budget. Same evaluation set."><div className="winner-card"><small>Best observed strategy</small><h3>Hybrid Sampling</h3><strong>.441 <span>mAP50–95</span></strong><p>+0.016 vs Entropy at the same 16k labeled budget.</p></div><div className="comparison-deltas"><StatRow label="mAP50–95" value=".441 vs .425 · +.016"/><StatRow label="Recall" value=".731 vs .711 · +.020"/><StatRow label="VRU Recall" value=".674 vs .638 · +.036"/><StatRow label="Night Recall" value=".608 vs .566 · +.042"/><StatRow label="Rain/Fog Recall" value=".571 vs .529 · +.042"/></div></Panel></div>
    <section className="comparison-table-card"><div><h3>Controlled comparison</h3><p>Each row represents a model trained from that strategy's cumulative labeled dataset, then evaluated on Fixed Holdout v1.</p></div><div className="table-scroll"><table><thead><tr><th>Budget</th><th>Entropy Sampling</th><th>Hybrid Sampling</th><th>Hybrid Δ</th></tr></thead><tbody>{points.map(p=><tr key={p.label}><td><strong>{count(p.samples)}</strong><small>{p.label}</small></td><td>{p.entropy.toFixed(3)}</td><td><strong>{p.hybrid.toFixed(3)}</strong></td><td>{p.samples===8000?'—':`+${(p.hybrid-p.entropy).toFixed(3)}`}</td></tr>)}</tbody></table></div></section>
    <div className="comparison-note"><CheckCircle2 size={16}/><div><strong>What this comparison means</strong><p>RoadSift is comparing models, not datasets directly. Dataset quality is inferred from downstream model performance under controlled training and a shared fixed holdout.</p></div></div>
  </div>;
}
